-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(id INTEGER, status TEXT, amount INTEGER);
-- INSERT INTO orders VALUES(1,'done',30),(2,'open',90),(3,'open',100),(4,'cancel',200),(5,'open',NULL);
SELECT id FROM orders
WHERE status = 'done' OR status = 'open' AND amount >= 100
ORDER BY id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(status TEXT, amount INTEGER);
-- INSERT INTO orders VALUES('done',10),('done',30),('open',50);
SELECT
    AVG(CASE WHEN status = 'done' THEN amount END),
    ROUND(AVG(CASE WHEN status = 'done' THEN amount ELSE 0 END), 2)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id INTEGER, budget INTEGER);
-- INSERT INTO customers VALUES(1,10),(2,10);
-- CREATE TABLE orders(customer_id INTEGER, amount INTEGER);
-- INSERT INTO orders VALUES(1,4),(1,6),(2,3);
WITH totals AS (
    SELECT customer_id, SUM(amount) AS spent
    FROM orders GROUP BY customer_id
)
SELECT SUM(c.budget), SUM(t.spent)
FROM customers AS c
LEFT JOIN totals AS t ON c.id = t.customer_id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE users(org TEXT, user_id INTEGER);
-- INSERT INTO users VALUES('A',1),('B',1);
-- CREATE TABLE orders(org TEXT, user_id INTEGER, amount INTEGER);
-- INSERT INTO orders VALUES('A',1,10),('A',1,20),('B',1,30);
SELECT COUNT(*) FROM users AS u
JOIN orders AS o
  ON u.org = o.org AND u.user_id = o.user_id;

